import { readFile } from "node:fs/promises";
import { Haau3, type fhir4 } from "@haau3/sdk";

const haau3 = new Haau3(); // reads HAAU3_API_KEY
// request.json holds a pharmacy benefit check without patient details, as a Bundle.
const body: fhir4.Bundle = JSON.parse(await readFile("request.json", "utf8"));
const bundle = await haau3.processMessage(body);
console.log(bundle.entry?.length ?? 0);

